function findMiddleware<T>(middleware: Record<string, T[]>, path: string): T[] | undefined {
  for (const k of Object.keys(middleware).sort((a, b) => b.length - a.length)) {
    if (buildWildcardRegExp(k).test(path)) {
      return [...middleware[k]]
    }
  }

  return undefined
}

