isObjectRestDestructuring(node: TSESTree.Node): boolean {
  if (node.type !== AST_NODE_TYPES.ObjectPattern) {
    return false
  }
  return node.properties.some((p) => p.type === AST_NODE_TYPES.RestElement)
},

