import type {
  ParserServices,
  ParserServicesWithTypeInformation,
  TSESTree,
} from '@typescript-eslint/utils'

functions.code:
isQueryResultCall(
  node: TSESTree.CallExpression,
  parserServices: Partial<ParserServices> | null | undefined,
): boolean {
  if (!parserServices?.program || !parserServices.esTreeNodeToTSNodeMap) {
    return false
  }
  const checker = parserServices.program.getTypeChecker()
  const tsNode = parserServices.esTreeNodeToTSNodeMap.get(node.callee)
  const signatures = checker.getTypeAtLocation(tsNode).getCallSignatures()
  return signatures.some((sig) => isQueryResultType(sig.getReturnType()))
},

imports:
import type {
  ParserServices,
  ParserServicesWithTypeInformation,
  TSESTree,
} from '@typescript-eslint/utils'

functions.code:
function getReactHook(node: TSESTree.CallExpression): string | undefined {
  if (node.callee.type === 'Identifier') {
    const calleeName = node.callee.name
    // Check if the identifier is a known React hook or an alias
    if (reactHookNames.includes(calleeName) || calleeName in hookAliasMap) {
      return calleeName
    }
  } else if (
    node.callee.type === 'MemberExpression' &&
    node.callee.object.type === 'Identifier' &&
    node.callee.object.name === 'React' &&
    node.callee.property.type === 'Identifier' &&
    reactHookNames.includes(node.callee.property.name)
  ) {
    // Member expression case: `React.useCallback`
    return node.callee.property.name
  }
  return undefined
}

function collectVariableNames(
  pattern: TSESTree.BindingName,
  queryHook: string,
) {
  if (pattern.type === AST_NODE_TYPES.Identifier) {
    trackedVariables[pattern.name] = queryHook
  } else if (pattern.type === AST_NODE_TYPES.ArrayPattern) {
    for (const element of pattern.elements) {
      if (element === null) {
        continue
      }
      if (element.type === AST_NODE_TYPES.Identifier) {
        trackedVariables[element.name] = queryHook
      } else if (
        element.type === AST_NODE_TYPES.RestElement &&
        element.argument.type === AST_NODE_TYPES.Identifier
      ) {
        trackedVariables[element.argument.name] = queryHook
      }
    }
  }
}

function isCustomHookName(hookName: string): boolean {
  return /^use[A-Z0-9]/.test(hookName)
}

function hasCombineProperty(
  callExpression: TSESTree.CallExpression,
): boolean {
  if (callExpression.arguments.length === 0) return false

  const firstArg = callExpression.arguments[0]
  if (!firstArg || firstArg.type !== AST_NODE_TYPES.ObjectExpression)
    return false

  return firstArg.properties.some(
    (prop) =>
      prop.type === AST_NODE_TYPES.Property &&
      prop.key.type === AST_NODE_TYPES.Identifier &&
      prop.key.name === 'combine',
  )
}

function getDirectQueryHook(
  callExpression: TSESTree.CallExpression,
): string | undefined {
  if (
    callExpression.callee.type !== AST_NODE_TYPES.Identifier ||
    !allHookNames.includes(callExpression.callee.name) ||
    !helpers.isTanstackQueryImport(callExpression.callee)
  ) {
    return undefined
  }

  if (
    (callExpression.callee.name === 'useQueries' ||
      callExpression.callee.name === 'useSuspenseQueries') &&
    hasCombineProperty(callExpression)
  ) {
    return undefined
  }

  return callExpression.callee.name
}

function getTrackedQueryHook(
  callExpression: TSESTree.CallExpression,
): string | undefined {
  const directQueryHook = getDirectQueryHook(callExpression)
  if (directQueryHook !== undefined) {
    return directQueryHook
  }

  if (callExpression.callee.type === AST_NODE_TYPES.Identifier) {
    return trackedCustomHooks[callExpression.callee.name]
  }

  return undefined
}

function getReturnedQueryHook(
  body:
    | TSESTree.FunctionExpression['body']
    | TSESTree.ArrowFunctionExpression['body'],
): string | undefined {
  if (body.type === AST_NODE_TYPES.CallExpression) {
    return getDirectQueryHook(body)
  }

  if (body.type !== AST_NODE_TYPES.BlockStatement) {
    return undefined
  }

  const returnStatements = body.body.filter(
    (statement): statement is TSESTree.ReturnStatement =>
      statement.type === AST_NODE_TYPES.ReturnStatement,
  )
  if (returnStatements.length !== 1) {
    return undefined
  }

  const returnArgument = returnStatements[0]?.argument
  if (returnArgument?.type === AST_NODE_TYPES.CallExpression) {
    return getDirectQueryHook(returnArgument)
  }

  return undefined
}

function checkDependencyArray(
  reactHook: string,
  depsArray: TSESTree.ArrayExpression,
) {
  depsArray.elements.forEach((dep) => {
    if (
      dep !== null &&
      dep.type === AST_NODE_TYPES.Identifier &&
      trackedVariables[dep.name] !== undefined
    ) {
      const queryHook = trackedVariables[dep.name]
      context.report({
        node: dep,
        messageId: 'noUnstableDeps',
        data: {
          queryHook,
          reactHook,
        },
      })
    }
  })
}

ImportDeclaration(node: TSESTree.ImportDeclaration) {
  if (
    node.specifiers.length > 0 &&
    node.importKind === 'value' &&
    node.source.value === 'React'
  ) {
    node.specifiers.forEach((specifier) => {
      if (
        specifier.type === AST_NODE_TYPES.ImportSpecifier &&
        specifier.imported.type === AST_NODE_TYPES.Identifier &&
        reactHookNames.includes(specifier.imported.name)
      ) {
        // Track alias or direct import
        hookAliasMap[specifier.local.name] = specifier.imported.name
      }
    })
  }
},

FunctionDeclaration(node) {
  if (node.id === null || !isCustomHookName(node.id.name)) {
    return
  }

  const queryHook = getReturnedQueryHook(node.body)
  if (queryHook !== undefined) {
    trackedCustomHooks[node.id.name] = queryHook
  }
},

VariableDeclarator(node) {
  if (
    node.id.type === AST_NODE_TYPES.Identifier &&
    isCustomHookName(node.id.name) &&
    node.init !== null &&
    (node.init.type === AST_NODE_TYPES.ArrowFunctionExpression ||
      node.init.type === AST_NODE_TYPES.FunctionExpression)
  ) {
    const queryHook = getReturnedQueryHook(node.init.body)
    if (queryHook !== undefined) {
      trackedCustomHooks[node.id.name] = queryHook
    }
  }

  if (
    node.init !== null &&
    node.init.type === AST_NODE_TYPES.CallExpression
  ) {
    pendingVariableDeclarators.push(node)
  }
},

'Program:exit'() {
  pendingVariableDeclarators.forEach((node) => {
    if (node.init?.type !== AST_NODE_TYPES.CallExpression) {
      return
    }

    const queryHook = getTrackedQueryHook(node.init)
    if (queryHook !== undefined) {
      collectVariableNames(node.id, queryHook)
    }
  })

  pendingDependencyChecks.forEach(({ reactHook, depsArray }) => {
    checkDependencyArray(reactHook, depsArray)
  })
},

Property(node) {
  if (
    !ASTUtils.isObjectExpression(node.parent) ||
    !ASTUtils.isIdentifierWithName(node.key, 'queryFn')
  ) {
    return
  }

  const parserServices = context.sourceCode.parserServices

  if (
    !parserServices ||
    !parserServices.esTreeNodeToTSNodeMap ||
    !parserServices.program
  ) {
    return
  }

  const checker = parserServices.program.getTypeChecker()
  const tsNode = parserServices.esTreeNodeToTSNodeMap.get(node.value)
  const type = checker.getTypeAtLocation(tsNode)

  // Get the return type of the function
  if (type.getCallSignatures().length > 0) {
    const returnType = type.getCallSignatures()[0]?.getReturnType()

    if (!returnType) {
      return
    }

    // Check if return type is void or undefined
    if (isIllegalReturn(checker, returnType)) {
      context.report({
        node: node.value,
        messageId: 'noVoidReturn',
      })
    }
  }
},

function isIllegalReturn(checker: TypeChecker, type: Type): boolean {
  const awaited = checker.getAwaitedType(type)

  if (!awaited) return false

  if (awaited.isUnion()) {
    return awaited.types.some((t) => isIllegalReturn(checker, t))
  }

  const typeString = checker.typeToString(awaited)
  return typeString === 'void' || typeString === 'undefined'
}

function reportInlineQueryOptions(node: TSESTree.Node): void {
  if (ASTUtils.isObjectExpression(node) && hasInlineQueryOptions(node)) {
    context.report({
      node,
      messageId: 'preferQueryOptions',
    })
  }
}

function reportInlineFilterQueryKey(node: TSESTree.Node): void {
  if (ASTUtils.isObjectExpression(node) && hasInlineFilterQueryKey(node)) {
    context.report({
      node,
      messageId: 'preferQueryOptionsQueryKey',
    })
  }
}

function hasInlineQueryOptions(node: TSESTree.ObjectExpression): boolean {
  return (
    ASTUtils.findPropertyWithIdentifierKey(node.properties, 'queryKey') !==
      undefined ||
    ASTUtils.findPropertyWithIdentifierKey(node.properties, 'queryFn') !==
      undefined
  )
}

function hasInlineFilterQueryKey(node: TSESTree.ObjectExpression): boolean {
  const queryKey = ASTUtils.findPropertyWithIdentifierKey(
    node.properties,
    'queryKey',
  )?.value

  return queryKey !== undefined && isInlineArrayExpression(queryKey)
}

function isInlineArrayExpression(node: TSESTree.Node): boolean {
  return unwrapTypeAssertions(node).type === AST_NODE_TYPES.ArrayExpression
}

function getReturnedObjectExpressions(
  node: TSESTree.Node,
): Array<TSESTree.ObjectExpression> {
  if (ASTUtils.isObjectExpression(node)) {
    return [node]
  }

  if (
    node.type === AST_NODE_TYPES.ArrowFunctionExpression ||
    node.type === AST_NODE_TYPES.FunctionExpression
  ) {
    return getReturnedObjectExpressions(node.body)
  }

  if (node.type === AST_NODE_TYPES.BlockStatement) {
    return node.body.flatMap((statement) => {
      if (
        statement.type === AST_NODE_TYPES.ReturnStatement &&
        statement.argument !== null
      ) {
        return getReturnedObjectExpressions(statement.argument)
      }

      return []
    })
  }

  if (node.type === AST_NODE_TYPES.ConditionalExpression) {
    return [
      ...getReturnedObjectExpressions(node.consequent),
      ...getReturnedObjectExpressions(node.alternate),
    ]
  }

  if (node.type === AST_NODE_TYPES.LogicalExpression) {
    return [
      ...getReturnedObjectExpressions(node.left),
      ...getReturnedObjectExpressions(node.right),
    ]
  }

  if (node.type === AST_NODE_TYPES.SequenceExpression) {
    return node.expressions.flatMap((expression) =>
      getReturnedObjectExpressions(expression),
    )
  }

  return []
}

function getQueryObjects(
  node: TSESTree.Node,
): Array<TSESTree.ObjectExpression> {
  if (node.type === AST_NODE_TYPES.ArrayExpression) {
    return node.elements.flatMap((element) => {
      if (element !== null && ASTUtils.isObjectExpression(element)) {
        return [element]
      }

      return []
    })
  }

  if (
    node.type === AST_NODE_TYPES.CallExpression &&
    node.callee.type === AST_NODE_TYPES.MemberExpression &&
    ASTUtils.isIdentifierWithName(node.callee.property, 'map')
  ) {
    const mapper = node.arguments[0]

    if (
      mapper?.type === AST_NODE_TYPES.ArrowFunctionExpression ||
      mapper?.type === AST_NODE_TYPES.FunctionExpression
    ) {
      return getReturnedObjectExpressions(mapper)
    }
  }

  return []
}

function isTanstackQueryClient(
  node: TSESTree.Node,
  context: Readonly<TSESLint.RuleContext<string, ReadonlyArray<unknown>>>,
  helpers: Helpers,
): boolean {
  const source = resolveQueryClientSource(node, context)

  if (
    source.type === AST_NODE_TYPES.CallExpression &&
    ASTUtils.isIdentifier(source.callee)
  ) {
    return (
      getTanstackImportName(context, helpers, source.callee) ===
      'useQueryClient'
    )
  }

  if (
    source.type === AST_NODE_TYPES.NewExpression &&
    ASTUtils.isIdentifier(source.callee)
  ) {
    return (
      getTanstackImportName(context, helpers, source.callee) === 'QueryClient'
    )
  }

  return false
}

function getTanstackImportName(
  context: Readonly<TSESLint.RuleContext<string, ReadonlyArray<unknown>>>,
  helpers: Helpers,
  node: TSESTree.Identifier,
): string | null {
  if (!helpers.isTanstackQueryImport(node)) {
    return null
  }

  const definition = context.sourceCode
    .getScope(node)
    .references.find((reference) => reference.identifier === node)?.resolved
    ?.defs[0]?.node

  if (
    definition?.type !== AST_NODE_TYPES.ImportSpecifier ||
    definition.imported.type !== AST_NODE_TYPES.Identifier
  ) {
    return null
  }

  return definition.imported.name
}

function resolveQueryClientSource(
  node: TSESTree.Node,
  context: Readonly<TSESLint.RuleContext<string, ReadonlyArray<unknown>>>,
): TSESTree.Node {
  const visitedNodes = new Set<TSESTree.Node>()

  while (!visitedNodes.has(node)) {
    visitedNodes.add(node)

    if (node.type === AST_NODE_TYPES.ChainExpression) {
      node = node.expression
      continue
    }

    node = unwrapTypeAssertions(node)

    if (node.type !== AST_NODE_TYPES.Identifier) {
      return node
    }

    const expression = ASTUtils.getReferencedExpressionByIdentifier({
      context,
      node,
    })

    if (expression === null) {
      return node
    }

    node = expression
  }

  return node
}

function unwrapTypeAssertions(node: TSESTree.Node): TSESTree.Node {
  while (
    node.type === AST_NODE_TYPES.TSAsExpression ||
    node.type === AST_NODE_TYPES.TSSatisfiesExpression ||
    node.type === AST_NODE_TYPES.TSTypeAssertion
  ) {
    node = node.expression
  }

  return node
}

isNodeOfOneOf<T extends AST_NODE_TYPES>(
  node: TSESTree.Node,
  types: ReadonlyArray<T>,
): node is TSESTree.Node & { type: T } {
  return types.includes(node.type as T)
},

isIdentifier(node: TSESTree.Node): node is TSESTree.Identifier {
  return node.type === AST_NODE_TYPES.Identifier
},

isIdentifierWithName(
  node: TSESTree.Node,
  name: string,
): node is TSESTree.Identifier {
  return ASTUtils.isIdentifier(node) && node.name === name
},

isIdentifierWithOneOfNames<T extends Array<string>>(
  node: TSESTree.Node,
  name: T,
): node is TSESTree.Identifier & { name: T[number] } {
  return ASTUtils.isIdentifier(node) && name.includes(node.name)
},

isProperty(node: TSESTree.Node): node is TSESTree.Property {
  return node.type === AST_NODE_TYPES.Property
},

isObjectExpression(node: TSESTree.Node): node is TSESTree.ObjectExpression {
  return node.type === AST_NODE_TYPES.ObjectExpression
},

isPropertyWithIdentifierKey(
  node: TSESTree.Node,
  key: string,
): node is TSESTree.Property {
  return (
    ASTUtils.isProperty(node) && ASTUtils.isIdentifierWithName(node.key, key)
  )
},

findPropertyWithIdentifierKey(
  properties: Array<TSESTree.ObjectLiteralElement>,
  key: string,
): TSESTree.Property | undefined {
  return properties.find((x): x is TSESTree.Property =>
    ASTUtils.isPropertyWithIdentifierKey(x, key),
  )
},

traverseUpOnly(
  identifier: TSESTree.Node,
  allowedNodeTypes: Array<AST_NODE_TYPES>,
): TSESTree.Node {
  const parent = identifier.parent

  if (parent !== undefined && allowedNodeTypes.includes(parent.type)) {
    return ASTUtils.traverseUpOnly(parent, allowedNodeTypes)
  }

  return identifier
},

traverseUpMemberExpression(node: TSESTree.Node): TSESTree.Node {
  const parent = node.parent

  if (
    parent !== undefined &&
    ((parent.type === AST_NODE_TYPES.MemberExpression &&
      parent.object === node) ||
      parent.type === AST_NODE_TYPES.ChainExpression ||
      parent.type === AST_NODE_TYPES.TSNonNullExpression)
  ) {
    return ASTUtils.traverseUpMemberExpression(parent)
  }

  return node
},

isDeclaredInNode(params: {
  functionNode: TSESTree.Node
  reference: TSESLint.Scope.Reference
  scopeManager: TSESLint.Scope.ScopeManager
}) {
  const { functionNode, reference, scopeManager } = params
  const scope = scopeManager.acquire(functionNode)

  if (scope === null) {
    return false
  }

  return scope.set.has(reference.identifier.name)
},

getExternalRefs(params: {
  scopeManager: TSESLint.Scope.ScopeManager
  sourceCode: Readonly<TSESLint.SourceCode>
  node: TSESTree.Node
}): Array<TSESLint.Scope.Reference> {
  const { scopeManager, sourceCode, node } = params
  const scope = scopeManager.acquire(node)

  if (scope === null) {
    return []
  }

  const collectReferences = (
    currentScope: TSESLint.Scope.Scope,
  ): Array<TSESLint.Scope.Reference> => {
    const references = [...currentScope.references]

    for (const childScope of currentScope.childScopes) {
      references.push(...collectReferences(childScope))
    }

    return references
  }

  const references = collectReferences(scope)
    .filter((x) => x.isRead() && !scope.set.has(x.identifier.name))
    .map((x) => {
      const memberPath = ASTUtils.traverseUpMemberExpression(x.identifier)
      const memberExpression = memberPath.parent
      const isComputedCallProperty =
        memberExpression !== undefined &&
        memberExpression.type === AST_NODE_TYPES.MemberExpression &&
        memberExpression.computed &&
        memberExpression.property === memberPath &&
        memberExpression.parent.type === AST_NODE_TYPES.CallExpression &&
        memberExpression.parent.callee === memberExpression

      const referenceNode = isComputedCallProperty
        ? memberPath
        : ASTUtils.traverseUpOnly(x.identifier, [
            AST_NODE_TYPES.MemberExpression,
            AST_NODE_TYPES.Identifier,
          ])

      return {
        variable: x,
        node: referenceNode,
        text: sourceCode.getText(referenceNode),
      }
    })

  const localRefIds = new Set(
    [...scope.set.values()].map((x) => sourceCode.getText(x.identifiers[0])),
  )

  const externalRefs = references.filter(
    (x) => x.variable.resolved === null || !localRefIds.has(x.text),
  )

  return uniqueBy(externalRefs, (x) => x.text).map((x) => x.variable)
},

isValidReactComponentOrHookName(
  identifier: TSESTree.Identifier | null | undefined,
) {
  return (
    identifier !== null &&
    identifier !== undefined &&
    /^(use|[A-Z])/.test(identifier.name)
  )
},

getFunctionAncestor(
  sourceCode: Readonly<TSESLint.SourceCode>,
  node: TSESTree.Node,
) {
  for (const ancestor of sourceCode.getAncestors(node)) {
    if (
      ASTUtils.isNodeOfOneOf(ancestor, [
        AST_NODE_TYPES.FunctionDeclaration,
        AST_NODE_TYPES.FunctionExpression,
        AST_NODE_TYPES.ArrowFunctionExpression,
      ])
    ) {
      return ancestor
    }

    if (
      ancestor.parent?.type === AST_NODE_TYPES.VariableDeclarator &&
      ancestor.parent.id.type === AST_NODE_TYPES.Identifier &&
      ASTUtils.isNodeOfOneOf(ancestor, [
        AST_NODE_TYPES.FunctionDeclaration,
        AST_NODE_TYPES.FunctionExpression,
        AST_NODE_TYPES.ArrowFunctionExpression,
      ])
    ) {
      return ancestor
    }
  }

  return undefined
},

getReferencedExpressionByIdentifier(params: {
  node: TSESTree.Node
  context: Readonly<TSESLint.RuleContext<string, ReadonlyArray<unknown>>>
}) {
  const { node, context } = params

  // we need the fallbacks for backwards compat with eslint < 8.37.0
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
  const sourceCode = context.sourceCode ?? context.getSourceCode()
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
  const scope = context.sourceCode.getScope(node)
    ? sourceCode.getScope(node)
    : context.getScope()

  const resolvedNode = scope.references.find((ref) => ref.identifier === node)
    ?.resolved?.defs[0]?.node

  if (resolvedNode?.type !== AST_NODE_TYPES.VariableDeclarator) {
    return null
  }

  return resolvedNode.init
},

export function createPropertyOrderRule<
  TFunc extends string,
  TProp extends string,
>(
  options: Omit<Parameters<typeof createRule>[0], 'create'>,
  targetFunctions: ReadonlyArray<TFunc> | Array<TFunc>,
  orderRules: ReadonlyArray<
    Readonly<[ReadonlyArray<TProp>, ReadonlyArray<TProp>]>
  >,
) {
  const targetFunctionSet = new Set(targetFunctions)
  function isTargetFunction(node: any): node is TFunc {
    return targetFunctionSet.has(node)
  }

  return createRule({
    ...options,
    create: detectTanstackQueryImports((context) => {
      return {
        CallExpression(node) {
          if (node.callee.type !== AST_NODE_TYPES.Identifier) {
            return
          }
          const functions = node.callee.name
          if (!isTargetFunction(functions)) {
            return
          }
          const argument = node.arguments[0]
          if (argument === undefined || argument.type !== 'ObjectExpression') {
            return
          }

          const allProperties = argument.properties

          // no need to sort if there is at max 1 property
          if (allProperties.length < 2) {
            return
          }

          const properties = allProperties.flatMap((p, index) => {
            if (
              p.type === AST_NODE_TYPES.Property &&
              p.key.type === AST_NODE_TYPES.Identifier
            ) {
              return { name: p.key.name, property: p }
            } else return { name: `_property_${index}`, property: p }
          })

          const sortedProperties = sortDataByOrder(
            properties,
            orderRules,
            'name',
          )
          if (sortedProperties === null) {
            return
          }

          context.report({
            node: argument,
            data: { function: node.callee.name },
            messageId: 'invalidOrder',
            fix(fixer) {
              const sourceCode = context.sourceCode

              const reorderedText = sortedProperties.reduce(
                (sourceText, specifier, index) => {
                  let textBetweenProperties = ''
                  if (index < allProperties.length - 1) {
                    textBetweenProperties = sourceCode
                      .getText()
                      .slice(
                        allProperties[index]!.range[1],
                        allProperties[index + 1]!.range[0],
                      )
                  }
                  return (
                    sourceText +
                    sourceCode.getText(specifier.property) +
                    textBetweenProperties
                  )
                },
                '',
              )
              return fixer.replaceTextRange(
                [allProperties[0]!.range[0], allProperties.at(-1)!.range[1]],
                reorderedText,
              )
            },
          })
        },
      }
    }),
  })
}

export function detectTanstackQueryImports(create: EnhancedCreate): Create {
  return (context, optionsWithDefault) => {
    const tanstackQueryImportSpecifiers: Array<TSESTree.ImportClause> = []

    const helpers: Helpers = {
      isSpecificTanstackQueryImport(node, source) {
        return !!tanstackQueryImportSpecifiers.find((specifier) => {
          if (
            specifier.type === TSESTree.AST_NODE_TYPES.ImportSpecifier &&
            specifier.parent.type ===
              TSESTree.AST_NODE_TYPES.ImportDeclaration &&
            specifier.parent.source.value === source
          ) {
            return node.name === specifier.local.name
          }

          return false
        })
      },
      isTanstackQueryImport(node) {
        return !!tanstackQueryImportSpecifiers.find((specifier) => {
          if (specifier.type === TSESTree.AST_NODE_TYPES.ImportSpecifier) {
            return node.name === specifier.local.name
          }

          return false
        })
      },
    }

    const detectionInstructions: TSESLint.RuleListener = {
      ImportDeclaration(node) {
        if (
          node.specifiers.length > 0 &&
          // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
          (node.importKind === 'value' || node.importKind === undefined) &&
          node.source.value.startsWith('@tanstack/') &&
          node.source.value.endsWith('-query')
        ) {
          tanstackQueryImportSpecifiers.push(...node.specifiers)
        }
      },
    }

    // Call original rule definition
    const ruleInstructions = create(context, optionsWithDefault, helpers)
    const enhancedRuleInstructions: TSESLint.RuleListener = {}

    const allKeys = new Set(
      Object.keys(detectionInstructions).concat(Object.keys(ruleInstructions)),
    )

    // Iterate over ALL instructions keys so we can override original rule instructions
    // to prevent their execution if conditions to report errors are not met.
    allKeys.forEach((instruction) => {
      enhancedRuleInstructions[instruction] = (node) => {
        if (instruction in detectionInstructions) {
          detectionInstructions[instruction]?.(node)
        }

        const ruleInstruction = ruleInstructions[instruction]

        // TODO: canReportErrors()
        if (ruleInstruction) {
          return ruleInstruction(node)
        }

        return undefined
      }
    })

    return enhancedRuleInstructions
  }
}

export function sortDataByOrder<T, TKey extends keyof T>(
  data: Array<T> | ReadonlyArray<T>,
  orderRules: ReadonlyArray<
    Readonly<[ReadonlyArray<T[TKey]>, ReadonlyArray<T[TKey]>]>
  >,
  key: TKey,
): Array<T> | null {
  const getSubsetIndex = (
    item: T[TKey],
    subsets: ReadonlyArray<ReadonlyArray<T[TKey]> | Array<T[TKey]>>,
  ): number | null => {
    for (let i = 0; i < subsets.length; i++) {
      if (subsets[i]?.includes(item)) {
        return i
      }
    }
    return null
  }

  const orderSets = orderRules.reduce(
    (sets, [A, B]) => [...sets, A, B],
    [] as Array<ReadonlyArray<T[TKey]> | Array<T[TKey]>>,
  )

  const inOrderArray = data.filter(
    (item) => getSubsetIndex(item[key], orderSets) !== null,
  )

  let wasResorted = false as boolean

  // Sort by the relative order defined by the rules
  const sortedArray = inOrderArray.sort((a, b) => {
    const aKey = a[key],
      bKey = b[key]
    const aSubsetIndex = getSubsetIndex(aKey, orderSets)
    const bSubsetIndex = getSubsetIndex(bKey, orderSets)

    // If both items belong to different subsets, sort by their subset order
    if (
      aSubsetIndex !== null &&
      bSubsetIndex !== null &&
      aSubsetIndex !== bSubsetIndex
    ) {
      return aSubsetIndex - bSubsetIndex
    }

    // If both items belong to the same subset or neither is in the subset, keep their relative order
    return 0
  })

  const inOrderIterator = sortedArray.values()
  const result = data.map((item) => {
    if (getSubsetIndex(item[key], orderSets) !== null) {
      const sortedItem = inOrderIterator.next().value!
      if (sortedItem[key] !== item[key]) {
        wasResorted = true
      }
      return sortedItem
    }
    return item
  })

  if (!wasResorted) {
    return null
  }
  return result
}

export function uniqueBy<T>(arr: Array<T>, fn: (x: T) => unknown): Array<T> {
  return arr.filter((x, i, a) => a.findIndex((y) => fn(x) === fn(y)) === i)
}

