private syncClient(): boolean {
  const nextClient = this.tryGetQueryClient()
  if (!nextClient) {
    this.unsubscribe?.()
    this.unsubscribe = undefined
    this.queryClient = undefined
    return false
  }

  if (nextClient === this.queryClient) {
    return true
  }

  this.unsubscribe?.()
  this.unsubscribe = undefined
  this.queryClient = nextClient
  return true
}

