function throttle<TArgs extends Array<any>>(
  func: (...args: TArgs) => any,
  wait = 100,
) {
  let timer: ManagedTimerId | null = null
  let params: TArgs
  return function (...args: TArgs) {
    params = args
    if (timer === null) {
      timer = timeoutManager.setTimeout(() => {
        func(...params)
        timer = null
      }, wait)
    }
  }
}

