}

export const getIsRestoringContext = (): Box<boolean> => {
  try {
    const isRestoring = getContext<Box<boolean> | undefined>(
      _isRestoringContextKey,
    )
    return isRestoring ?? { current: false }
  } catch (error) {
    return { current: false }
  }
}

