private requestFullReload(reason: string): void {
  if (this.reloadPending) return
  this.reloadPending = true
  this.logger.debug(`full reload needed: ${reason}`)
  this.send({
    type: 'custom',
    event: 'vite:bundled-dev:reload-needed',
    data: { reason },
  })
}

