export function isFutureDeprecationEnabled(
  config: ResolvedConfig,
  type: keyof FutureOptions,
): boolean {
  return !!config.future?.[type]
}

export function warnFutureDeprecation(
  config: ResolvedConfig,
  type: keyof FutureOptions,
  extraMessage?: string,
  stacktrace = true,
): void {
  if (
    _ignoreDeprecationWarnings ||
    !config.future ||
    config.future[type] !== 'warn'
  )
    return

  let msg = `[vite future] ${deprecationMessages[type]}`
  if (extraMessage) {
    msg += ` ${extraMessage}`
  }
  msg = colors.yellow(msg)

  const docs = `${docsURL}/changes/${deprecationCode[type].toLowerCase()}`
  msg +=
    colors.gray(`\n  ${stacktrace ? '├' : '└'}─── `) +
    colors.underline(docs) +
    '\n'

  if (stacktrace) {
    const stack = new Error().stack
    if (stack) {
      let stacks = stack
        .split('\n')
        .slice(3)
        .filter((i) => !i.includes('/node_modules/vite/dist/'))
      if (stacks.length === 0) {
        stacks.push('No stack trace found.')
      }
      stacks = stacks.map(
        (i, idx) => `  ${idx === stacks.length - 1 ? '└' : '│'} ${i.trim()}`,
      )
      msg += colors.dim(stacks.join('\n')) + '\n'
    }
  }
  config.logger.warnOnce(msg)
}

export function ignoreDeprecationWarnings<T>(fn: () => T): T {
  const before = _ignoreDeprecationWarnings
  _ignoreDeprecationWarnings = true
  const ret = fn()
  _ignoreDeprecationWarnings = before
  return ret
}

export function getEnvFilesForMode(
  mode: string,
  envDir: string | false,
): string[] {
  if (envDir !== false) {
    return [
      /** default file */ `.env`,
      /** local file */ `.env.local`,
      /** mode file */ `.env.${mode}`,
      /** mode local file */ `.env.${mode}.local`,
    ].map((file) => normalizePath(path.join(envDir, file)))
  }

  return []
}

export function loadEnv(
  mode: string,
  envDir: string | false,
  prefixes: string | string[] = 'VITE_',
): Record<string, string> {
  const start = performance.now()
  const getTime = () => `${(performance.now() - start).toFixed(2)}ms`

  if (mode === 'local') {
    throw new Error(
      `"local" cannot be used as a mode name because it conflicts with ` +
        `the .local postfix for .env files.`,
    )
  }
  prefixes = arraify(prefixes)
  const env: Record<string, string> = {}
  const envFiles = getEnvFilesForMode(mode, envDir)

  debug?.(`loading env files: %O`, envFiles)

  const parsed = Object.fromEntries(
    envFiles.flatMap((filePath) => {
      const stat = tryStatSync(filePath)
      // Support FIFOs (named pipes) for apps like 1Password
      if (!stat || (!stat.isFile() && !stat.isFIFO())) return []

      const parsedEnv = parseEnv(fs.readFileSync(filePath, 'utf-8'))
      return Object.entries(parsedEnv as Record<string, string>)
    }),
  )

  debug?.(`env files loaded in ${getTime()}`)

  // test NODE_ENV override before expand as otherwise process.env.NODE_ENV would override this
  if (parsed.NODE_ENV && process.env.VITE_USER_NODE_ENV === undefined) {
    process.env.VITE_USER_NODE_ENV = parsed.NODE_ENV
  }
  // support BROWSER and BROWSER_ARGS env variables
  if (parsed.BROWSER && process.env.BROWSER === undefined) {
    process.env.BROWSER = parsed.BROWSER
  }
  if (parsed.BROWSER_ARGS && process.env.BROWSER_ARGS === undefined) {
    process.env.BROWSER_ARGS = parsed.BROWSER_ARGS
  }

  // let environment variables use each other. make a copy of `process.env` so that `dotenv-expand`
  // doesn't re-assign the expanded values to the global `process.env`.
  const processEnv = { ...process.env } as DotenvPopulateInput
  expand({ parsed, processEnv })

  // only keys that start with prefix are exposed to client
  for (const [key, value] of Object.entries(parsed)) {
    if (prefixes.some((prefix) => key.startsWith(prefix))) {
      env[key] = value
    }
  }

  // Vite Task may know prefixed envs not present here; fetch them and let
  // the runner record each prefix in the build's cache key.
  for (const prefix of prefixes) {
    Object.assign(env, getEnvs({ prefix }))
  }

  // check if there are actual env variables starting with VITE_*
  // these are typically provided inline and should be prioritized
  for (const key in process.env) {
    if (prefixes.some((prefix) => key.startsWith(prefix))) {
      env[key] = process.env[key]!
    }
  }

  debug?.(`using resolved env: %O`, env)

  return env
}

export function resolveEnvPrefix({
  envPrefix = 'VITE_',
}: UserConfig): string[] {
  envPrefix = arraify(envPrefix)
  if (envPrefix.includes('')) {
    throw new Error(
      `envPrefix option contains value '', which could lead unexpected exposure of sensitive information.`,
    )
  }
  if (envPrefix.some((prefix) => /\s/.test(prefix))) {
    // eslint-disable-next-line no-console
    console.warn(
      colors.yellow(
        `[vite] Warning: envPrefix option contains values with whitespace, which does not work in practice.`,
      ),
    )
  }
  return envPrefix
}

export function perEnvironmentState<State>(
  initial: (environment: Environment) => State,
): (context: PluginContext) => State {
  const stateMap = new WeakMap<Environment, State>()
  return function (context: PluginContext) {
    const { environment } = context
    if (!stateMap.has(environment)) {
      stateMap.set(environment, initial(environment))
    }
    return stateMap.get(environment)!
  }
}

export function shouldExternalize(
  environment: Environment,
  id: string,
  importer: string | undefined,
): boolean {
  let isExternal = isExternalCache.get(environment)
  if (!isExternal) {
    isExternal = createIsExternal(environment)
    isExternalCache.set(environment, isExternal)
  }
  return isExternal(id, importer)
}

export function createIsConfiguredAsExternal(
  environment: PartialEnvironment,
): (id: string, importer?: string) => boolean {
  const { config } = environment
  const { root, resolve } = config
  const { external, noExternal } = resolve
  const noExternalFilter =
    typeof noExternal !== 'boolean' &&
    !(Array.isArray(noExternal) && noExternal.length === 0) &&
    createFilter(undefined, noExternal, { resolve: false })

  const targetConditions = resolve.externalConditions

  const resolveOptions: InternalResolveOptions = {
    ...resolve,
    root,
    isProduction: false,
    isBuild: true,
    conditions: targetConditions,
  }

  const isExternalizable = (
    id: string,
    importer: string | undefined,
    configuredAsExternal: boolean,
  ): boolean => {
    if (!bareImportRE.test(id) || id.includes('\0')) {
      return false
    }
    try {
      const resolved = tryNodeResolve(
        id,
        // Skip passing importer in build to avoid externalizing non-hoisted dependencies
        // unresolvable from root (which would be unresolvable from output bundles also)
        config.command === 'build' ? undefined : importer,
        resolveOptions,
        undefined,
        false,
      )
      if (!resolved) {
        return false
      }
      // Only allow linked packages to be externalized
      // if they are explicitly configured as external
      if (!configuredAsExternal && !isInNodeModules(resolved.id)) {
        return false
      }
      return canExternalizeFile(resolved.id)
    } catch {
      debug?.(
        `Failed to node resolve "${id}". Skipping externalizing it by default.`,
      )
      // may be an invalid import that's resolved by a plugin
      return false
    }
  }

  // Returns true if it is configured as external, false if it is filtered
  // by noExternal and undefined if it isn't affected by the explicit config
  return (id: string, importer?: string) => {
    if (
      // If this id is defined as external, force it as external
      // Note that individual package entries are allowed in `external`
      external !== true &&
      external.includes(id)
    ) {
      return true
    }
    const pkgName = getNpmPackageName(id)
    if (!pkgName) {
      return isExternalizable(id, importer, false)
    }
    if (
      // A package name in ssr.external externalizes every
      // externalizable package entry
      external !== true &&
      external.includes(pkgName)
    ) {
      return isExternalizable(id, importer, true)
    }
    if (typeof noExternal === 'boolean') {
      return !noExternal
    }
    if (noExternalFilter && !noExternalFilter(pkgName)) {
      return false
    }
    // If external is true, all will be externalized by default, regardless if
    // it's a linked package
    return isExternalizable(id, importer, external === true)
  }
}

function createIsExternal(
  environment: Environment,
): (id: string, importer?: string) => boolean {
  const processedIds = new Map<string, boolean>()

  const isConfiguredAsExternal = createIsConfiguredAsExternal(environment)

  return (id: string, importer?: string) => {
    if (processedIds.has(id)) {
      return processedIds.get(id)!
    }
    let isExternal = false
    if (id[0] !== '.' && !path.isAbsolute(id)) {
      isExternal =
        isBuiltin(environment.config.resolve.builtins, id) ||
        isConfiguredAsExternal(id, importer)
    }
    processedIds.set(id, isExternal)
    return isExternal
  }
}

export function canExternalizeFile(filePath: string): boolean {
  const ext = path.extname(filePath)
  // only external js imports
  return !ext || ext === '.js' || ext === '.mjs' || ext === '.cjs'
}

export async function resolveHttpServer(
  app: Connect.Server,
  httpsOptions?: HttpsServerOptions,
): Promise<HttpServer> {
  if (!httpsOptions) {
    const { createServer } = await import('node:http')
    return createServer(app)
  }

  const { createSecureServer } = await import('node:http2')
  return createSecureServer(
    {
      // Manually increase the session memory to prevent 502 ENHANCE_YOUR_CALM
      // errors on large numbers of requests
      maxSessionMemory: 1000,
      // Increase the stream reset rate limit to prevent net::ERR_HTTP2_PROTOCOL_ERROR
      // errors on large numbers of requests
      streamResetBurst: 100000,
      streamResetRate: 33,
      ...httpsOptions,
      allowHTTP1: true,
    },
    // @ts-expect-error TODO: is this correct?
    app,
  )
}

export async function resolveHttpsConfig(
  https: HttpsServerOptions | undefined,
): Promise<HttpsServerOptions | undefined> {
  if (!https) return undefined

  const [ca, cert, key, pfx] = await Promise.all([
    readFileIfExists(https.ca),
    readFileIfExists(https.cert),
    readFileIfExists(https.key),
    readFileIfExists(https.pfx),
  ])
  return { ...https, ca, cert, key, pfx }
}

async function readFileIfExists(value?: string | Buffer | any[]) {
  if (typeof value === 'string') {
    return fsp.readFile(path.resolve(value)).catch(() => value)
  }
  return value
}

async function getAvailableEphemeralPort(
  specifiedHost: string | undefined,
): Promise<number | null> {
  for (let attempt = 0; attempt < 3; attempt++) {
    // Passing 0 asks the OS for a new candidate on every attempt.
    // We assume that the OS will return a different candidate on every attempt,
    // which does not always hold true, but it should be fine for most cases.
    let port = 0
    let available = true
    for (const host of [...wildcardHosts, specifiedHost]) {
      // Gracefully handle errors (e.g., IPv6 disabled on the system)
      const availablePort = await tryListen(port, host).catch(() => port)
      if (availablePort == null) {
        available = false
        break
      }
      port = availablePort
    }
    if (available) return port
  }
  return null
}

async function isPortAvailable(port: number): Promise<boolean> {
  for (const host of wildcardHosts) {
    // Gracefully handle errors (e.g., IPv6 disabled on the system)
    const available = await tryListen(port, host).catch(() => true)
    if (!available) return false
  }
  return true
}

function tryListen(
  port: number,
  host: string | undefined,
): Promise<number | null> {
  return new Promise((resolve) => {
    const server = net.createServer()
    server.once('error', (e: NodeJS.ErrnoException) => {
      server.close(() => resolve(e.code === 'EADDRINUSE' ? null : port))
    })
    server.once('listening', () => {
      const address = server.address()
      server.close(() =>
        resolve(typeof address === 'object' && address ? address.port : port),
      )
    })
    server.listen(port, host)
  })
}

async function tryBindServer(
  httpServer: HttpServer,
  port: number,
  host: string | undefined,
): Promise<
  { success: true } | { success: false; error: NodeJS.ErrnoException }
> {
  return new Promise((resolve) => {
    const onError = (e: NodeJS.ErrnoException) => {
      httpServer.off('error', onError)
      httpServer.off('listening', onListening)
      resolve({ success: false, error: e })
    }
    const onListening = () => {
      httpServer.off('error', onError)
      httpServer.off('listening', onListening)
      resolve({ success: true })
    }

    httpServer.on('error', onError)
    httpServer.on('listening', onListening)

    httpServer.listen(port, host)
  })
}

export async function httpServerStart(
  httpServer: HttpServer,
  serverOptions: {
    port: number
    strictPort: boolean | undefined
    host: string | undefined
    logger: Logger
  },
): Promise<number> {
  const { port: startPort, strictPort, host, logger } = serverOptions

  if (startPort === 0) {
    const port = await getAvailableEphemeralPort(host)
    if (port == null) {
      throw new Error('No available ephemeral port found')
    }

    const result = await tryBindServer(httpServer, port, host)
    if (result.success) {
      return port
    }
    if (result.error.code !== 'EADDRINUSE') {
      throw result.error
    }
    // this can happen if the port was listened by other process between getAvailableEphemeralPort and tryBindServer
    throw new Error(`Port ${port} is already in use`)
  }

  for (let port = startPort; port <= MAX_PORT; port++) {
    // Pre-check port availability on wildcard addresses (0.0.0.0, ::)
    // so that we avoid conflicts with other servers listening on all interfaces
    const portAvailableOnWildcard = await isPortAvailable(port)

    // If port is not available on a wildcard address but strictPort is set,
    // we still try binding directly before giving up.
    if (strictPort) {
      const result = await tryBindServer(httpServer, port, host)
      if (result.success) {
        if (!portAvailableOnWildcard) {
          logger.warn(
            colors.yellow(
              `Port ${port} is in use on a wildcard address, but ${host ?? 'localhost'}:${port} is available. ` +
                `There may be another server running on a wildcard IP on port ${port}.`,
            ),
          )
        }
        return port
      }
      if (result.error.code !== 'EADDRINUSE') {
        throw result.error
      }
      throw new Error(`Port ${port} is already in use`)
    }

    if (portAvailableOnWildcard) {
      const result = await tryBindServer(httpServer, port, host)
      if (result.success) {
        return port
      }
      if (result.error.code !== 'EADDRINUSE') {
        throw result.error
      }
    }
    logger.info(`Port ${port} is in use, trying another one...`)
  }
  throw new Error(
    `No available ports found between ${startPort} and ${MAX_PORT}`,
  )
}

export function setClientErrorHandler(
  server: HttpServer,
  logger: Logger,
): void {
  server.on('clientError', (err, socket) => {
    // https://github.com/nodejs/node/blob/v26.2.0/lib/_http_server.js#L992
    let msg
    switch ((err as any).code) {
      case 'HPE_HEADER_OVERFLOW': {
        msg = '431 Request Header Fields Too Large'
        logger.warn(
          colors.yellow(
            'Server responded with status code 431. ' +
              'See https://vite.dev/guide/troubleshooting.html#_431-request-header-fields-too-large.',
          ),
        )
        break
      }
      case 'HPE_CHUNK_EXTENSIONS_OVERFLOW': {
        msg = '413 Payload Too Large'
        break
      }
      case 'ERR_HTTP_REQUEST_TIMEOUT': {
        msg = '408 Request Timeout'
        break
      }
      default: {
        msg = '400 Bad Request'
        break
      }
    }
    if ((err as any).code === 'ECONNRESET' || !socket.writable) {
      return
    }
    socket.end(`HTTP/1.1 ${msg}\r\nConnection: close\r\n\r\n`)
  })
}

export function createBackCompatIdResolver(
  config: ResolvedConfig,
  options?: Partial<InternalResolveOptions>,
): ResolveIdFn {
  const compatResolve = config.createResolver(options)
  let resolve: ResolveIdFn
  return async (environment, id, importer, aliasOnly) => {
    if (environment.name === 'client' || environment.name === 'ssr') {
      return compatResolve(id, importer, aliasOnly, environment.name === 'ssr')
    }
    resolve ??= createIdResolver(config, options)
    return resolve(environment, id, importer, aliasOnly)
  }
}

export function createIdResolver(
  config: ResolvedConfig,
  options?: Partial<InternalResolveOptions>,
): ResolveIdFn {
  const scan = options?.scan

  const pluginContainerMap = new Map<
    PartialEnvironment,
    EnvironmentPluginContainer
  >()
  async function resolve(
    environment: PartialEnvironment,
    id: string,
    importer?: string,
  ): Promise<PartialResolvedId | null> {
    let pluginContainer = pluginContainerMap.get(environment)
    if (!pluginContainer) {
      pluginContainer = await createEnvironmentPluginContainer(
        environment as Environment,
        [
          // @ts-expect-error  the aliasPlugin uses rollup types
          aliasPlugin({ entries: environment.config.resolve.alias }),
          ...oxcResolvePlugin(
            {
              root: config.root,
              isProduction: config.isProduction,
              isBuild: config.command === 'build',
              asSrc: true,
              preferRelative: false,
              tryIndex: true,
              ...options,
              // Ignore sideEffects and other computations as we only need the id
              idOnly: true,
            },
            environment.config,
            true,
          ),
        ],
        undefined,
        false,
      )
      pluginContainerMap.set(environment, pluginContainer)
    }
    return await pluginContainer.resolveId(id, importer, { scan })
  }

  const aliasOnlyPluginContainerMap = new Map<
    PartialEnvironment,
    EnvironmentPluginContainer
  >()
  async function resolveAlias(
    environment: PartialEnvironment,
    id: string,
    importer?: string,
  ): Promise<PartialResolvedId | null> {
    let pluginContainer = aliasOnlyPluginContainerMap.get(environment)
    if (!pluginContainer) {
      pluginContainer = await createEnvironmentPluginContainer(
        environment as Environment,
        // @ts-expect-error  the aliasPlugin uses rollup types
        [aliasPlugin({ entries: environment.config.resolve.alias })],
        undefined,
        false,
      )
      aliasOnlyPluginContainerMap.set(environment, pluginContainer)
    }
    return await pluginContainer.resolveId(id, importer, { scan })
  }

  return async (environment, id, importer, aliasOnly) => {
    const resolveFn = aliasOnly ? resolveAlias : resolve
    // aliasPlugin and resolvePlugin are implemented to function with a Environment only,
    // we cast it as PluginEnvironment to be able to use the pluginContainer
    const resolved = await resolveFn(environment, id, importer)
    return resolved?.id
  }
}

function getTimeFormatter() {
  timeFormatter ??= new Intl.DateTimeFormat(undefined, {
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
  })
  return timeFormatter
}

export function createLogger(
  level: LogLevel = 'info',
  options: LoggerOptions = {},
): Logger {
  if (options.customLogger) {
    return options.customLogger
  }

  const loggedErrors = new WeakSet<Error | RollupError>()
  const {
    prefix = '[vite]',
    allowClearScreen = true,
    console = globalThis.console,
  } = options
  const thresh = LogLevels[level]
  const canClearScreen =
    allowClearScreen && process.stdout.isTTY && !process.env.CI
  const clear = canClearScreen ? clearScreen : () => {}

  function format(type: LogType, msg: string, options: LogErrorOptions = {}) {
    if (options.timestamp) {
      let tag = ''
      if (type === 'info') {
        tag = colors.cyan(colors.bold(prefix))
      } else if (type === 'warn') {
        tag = colors.yellow(colors.bold(prefix))
      } else {
        tag = colors.red(colors.bold(prefix))
      }
      const environment = options.environment ? options.environment + ' ' : ''
      return `${colors.dim(getTimeFormatter().format(new Date()))} ${tag} ${environment}${msg}`
    } else {
      return msg
    }
  }

  function output(type: LogType, msg: string, options: LogErrorOptions = {}) {
    if (thresh >= LogLevels[type]) {
      const method = type === 'info' ? 'log' : type

      if (options.error) {
        loggedErrors.add(options.error)
      }
      if (canClearScreen) {
        if (type === lastType && msg === lastMsg) {
          sameCount++
          clear()
          console[method](
            format(type, msg, options),
            colors.yellow(`(x${sameCount + 1})`),
          )
        } else {
          sameCount = 0
          lastMsg = msg
          lastType = type
          if (options.clear) {
            clear()
          }
          console[method](format(type, msg, options))
        }
      } else {
        console[method](format(type, msg, options))
      }
    }
  }

  const warnedMessages = new Set<string>()

  const logger: Logger = {
    hasWarned: false,
    info(msg, opts) {
      output('info', msg, opts)
    },
    warn(msg, opts) {
      logger.hasWarned = true
      output('warn', msg, opts)
    },
    warnOnce(msg, opts) {
      if (warnedMessages.has(msg)) return
      logger.hasWarned = true
      output('warn', msg, opts)
      warnedMessages.add(msg)
    },
    error(msg, opts) {
      logger.hasWarned = true
      output('error', msg, opts)
    },
    clearScreen(type) {
      if (thresh >= LogLevels[type]) {
        clear()
      }
    },
    hasErrorLogged(error) {
      return loggedErrors.has(error)
    },
  }

  return logger
}

export function printServerUrls(
  urls: ResolvedServerUrls,
  optionsHost: string | boolean | undefined,
  info: Logger['info'],
): void {
  const colorUrl = (url: string) =>
    colors.cyan(url.replace(/:(\d+)\//, (_, port) => `:${colors.bold(port)}/`))
  for (const url of urls.local) {
    info(`  ${colors.green('➜')}  ${colors.bold('Local')}:   ${colorUrl(url)}`)
  }
  const networkUrlMaxLength = Math.max(
    ...urls.network.map((url) => url.length),
    0,
  )
  urls.network.forEach((url, index) => {
    const interfaceName = urls.networkInterfaceNames?.[index]
    let suffix = ''
    if (interfaceName) {
      const label =
        interfaceName.length > maxNetworkInterfaceNameLength
          ? `${interfaceName.slice(0, maxNetworkInterfaceNameLength - 1)}…`
          : interfaceName
      suffix =
        ' '.repeat(networkUrlMaxLength - url.length + 2) + colors.dim(label)
    }
    info(
      `  ${colors.green('➜')}  ${colors.bold('Network')}: ${colorUrl(url)}${suffix}`,
    )
  })
  if (urls.network.length === 0 && optionsHost === undefined) {
    info(
      colors.dim(`  ${colors.green('➜')}  ${colors.bold('Network')}: use `) +
        colors.bold('--host') +
        colors.dim(' to expose'),
    )
  }
}

export function classifyImportRef(
  ref: ConfigImportRef,
  resolvedId: string | null,
  file: string,
): NativeConfigIncompatibility | undefined {
  const { specifier, line, column } = ref
  const base = { file, line, column, specifier }

  if (specifier.endsWith('.json')) {
    if (!ref.hasTypeJsonAttribute) {
      return { type: 'json-without-attributes', ...base }
    }
    if (ref.namedImportLoc) {
      return {
        type: 'json-named-import',
        file,
        line: ref.namedImportLoc.line,
        column: ref.namedImportLoc.column,
        specifier,
      }
    }
    return undefined
  }

  if (!resolvedId) return undefined

  if (resolvedId.endsWith('.json')) {
    if (!ref.hasTypeJsonAttribute) {
      return { type: 'json-without-attributes', ...base }
    }
    if (ref.namedImportLoc) {
      return {
        type: 'json-named-import',
        file,
        line: ref.namedImportLoc.line,
        column: ref.namedImportLoc.column,
        specifier,
      }
    }
  }

  const lastSegment = lastSegmentOf(specifier)
  const specifierNamesIndex =
    lastSegment === 'index' || indexFileRE.test(lastSegment)

  if (indexFileRE.test(path.basename(resolvedId)) && !specifierNamesIndex) {
    return { type: 'directory-index-import', ...base }
  }
  if (!jsTsExtRE.test(lastSegment)) {
    return { type: 'extensionless-import', ...base }
  }
  return undefined
}

const hasTypeJson = (
  attributes: ESTree.ImportAttribute[] | undefined,
): boolean =>
  !!attributes?.some((attr) => {
    const key = attr.key.type === 'Identifier' ? attr.key.name : attr.key.value
    return key === 'type' && attr.value?.value === 'json'
  })

const findNonDefaultNamedBinding = (
  specifiers: ESTree.Node[],
): ESTree.Node | undefined =>
  specifiers.find((s) => {
    if (s.type === 'ImportSpecifier') {
      return !isDefaultModuleExportName(s.imported)
    }
    if (s.type === 'ExportSpecifier') {
      return !isDefaultModuleExportName(s.local)
    }
    return false
  })

export function analyzeConfigModuleReferences(
  code: string,
  ast: ESTree.Program,
  file: string,
): { globals: NativeConfigIncompatibility[]; imports: ConfigImportRef[] } {
  const imports: ConfigImportRef[] = []

  const addImportRef = (
    source: ESTree.StringLiteral,
    hasTypeJsonAttribute: boolean,
    namedBinding: ESTree.Node | undefined,
  ): void => {
    // bare specifiers are skipped except for the JSON checks, which classify
    // from the specifier alone (`vue/package.json` etc.)
    if (!isPathSpecifier(source.value) && !source.value.endsWith('.json')) {
      return
    }
    const { line, column } = numberToPos(code, source.start)
    const namedImportLoc = namedBinding
      ? numberToPos(code, namedBinding.start)
      : undefined
    imports.push({
      specifier: source.value,
      line,
      column,
      hasTypeJsonAttribute,
      namedImportLoc,
    })
  }

  eswalk(ast as any, {
    enter(_node) {
      const node = _node as ESTree.Node
      switch (node.type) {
        case 'ImportDeclaration':
          addImportRef(
            node.source,
            hasTypeJson(node.attributes),
            findNonDefaultNamedBinding(node.specifiers),
          )
          break
        case 'ExportNamedDeclaration':
        case 'ExportAllDeclaration':
          if (node.source)
            addImportRef(
              node.source,
              hasTypeJson(node.attributes),
              node.type === 'ExportNamedDeclaration'
                ? findNonDefaultNamedBinding(node.specifiers)
                : undefined,
            )
          break
        case 'ImportExpression':
          if (
            node.source.type === 'Literal' &&
            typeof node.source.value === 'string'
          ) {
            // if a second (options) arg is present, assume the required attributes is set
            addImportRef(node.source, node.options != null, undefined)
          }
          break
      }
    },
  })

  const globals: NativeConfigIncompatibility[] = []
  if (code.includes('__dirname') || code.includes('__filename')) {
    const { globals: freeReferences } = analyze(ast as any)
    for (const [name, type] of Object.entries(DIRNAME_FILENAME)) {
      const node = freeReferences.get(name) as ESTree.Node | undefined
      if (!node) continue
      const { line, column } = numberToPos(code, node.start)
      globals.push({ type, file, line, column })
    }
  }

  return { globals, imports }
}

export function findEsmSyntaxInCjs(
  code: string,
  ast: ESTree.Program,
  file: string,
): NativeConfigIncompatibility | undefined {
  for (const node of ast.body) {
    if (esmStatementTypes.has(node.type)) {
      const { line, column } = numberToPos(code, (node as ESTree.Node).start)
      return { type: 'esm-syntax-in-cjs', file, line, column }
    }
  }
  return undefined
}

function describeIncompatibility(
  item: NativeConfigIncompatibility,
  root: string,
): string {
  // 1-based column so terminals can link `file:line:column` to the exact position
  const loc = `${normalizePath(path.relative(root, item.file))}:${item.line}:${item.column + 1}`
  switch (item.type) {
    case 'dirname':
      return `\`__dirname\` (${loc}). Use \`import.meta.dirname\` instead`
    case 'filename':
      return `\`__filename\` (${loc}). Use \`import.meta.filename\` instead`
    case 'extensionless-import':
      return `import "${item.specifier}" without a file extension (${loc}). Add the file extension`
    case 'directory-index-import':
      return `import "${item.specifier}" resolves to a directory index (${loc}). Import the index file directly`
    case 'json-without-attributes':
      return item.specifier?.endsWith('.json')
        ? `JSON import "${item.specifier}" without import attributes (${loc}). Add \`with { type: 'json' }\``
        : `import "${item.specifier}" resolves to a JSON file (${loc}). Import it with a \`.json\` extension and \`with { type: 'json' }\``
    case 'json-named-import':
      return `named import from JSON module "${item.specifier}" (${loc}). JSON modules only provide a default export per spec. Use the default import and access the property`
    case 'esm-syntax-in-cjs':
      return `ESM syntax in a file loaded as CommonJS (${loc}). Use a \`.mjs\` extension or set \`"type": "module"\` in the closest package.json`
  }
}

export function formatNativeConfigIncompatWarning(
  items: NativeConfigIncompatibility[],
  root: string,
): string {
  const header =
    `Your Vite config uses features that are unsupported by ` +
    `\`configLoader: 'native'\`, which is planned to become the default in a ` +
    `future major version of Vite:`
  const lines = items.map((it) => `  - ${describeIncompatibility(it, root)}`)
  const footer = `Set \`VITE_CONFIG_NATIVE_IGNORE_WARNING=true\` to suppress this warning.`
  return colors.yellow([`(!) ${header}`, ...lines, footer].join('\n'))
}

export function createNativeConfigCompatPlugin(
  collector: NativeConfigIncompatibility[],
): Plugin {
  return {
    name: 'vite:native-config-compat-check',
    transform: {
      filter: {
        id: {
          include: jsTsExtRE,
          // exclude rolldown runtime
          exclude: /^\0/,
        },
      },
      async handler(code, id) {
        const isESM =
          typeof process.versions.deno === 'string' || isFilePathESM(id)

        let program: ESTree.Program
        try {
          const result = parseSync(id, code)
          if (result.errors.length > 0) return null
          program = result.program
        } catch {
          return null
        }

        // Node loads this file as CommonJS. ESM-only checks (`__dirname`,
        // import resolution) don't apply, but ESM syntax itself would throw
        // under the native loader.
        if (!isESM) {
          const finding = findEsmSyntaxInCjs(code, program, id)
          if (finding) collector.push(finding)
          return null
        }

        const { globals, imports } = analyzeConfigModuleReferences(
          code,
          program,
          id,
        )
        for (const g of globals) collector.push(g)
        for (const ref of imports) {
          let resolvedId: string | null = null
          if (
            !ref.specifier.endsWith('.json') &&
            !specifierHasJsExtension(ref.specifier)
          ) {
            const resolved = await this.resolve(ref.specifier, id)
            resolvedId = resolved?.id ?? null
          }
          const finding = classifyImportRef(ref, resolvedId, id)
          if (finding) collector.push(finding)
        }
        return null
      },
    },
  }
}

export function isDepOptimizationDisabled(
  optimizeDeps: DepOptimizationOptions,
): boolean {
  return (
    optimizeDeps.disabled === true ||
    optimizeDeps.disabled === 'dev' ||
    (!!optimizeDeps.noDiscovery && !optimizeDeps.include?.length)
  )
}

