function fullReload() {
  // Cached transform results have stale imports (resolved to
  // old locations) so they need to be invalidated before the page is
  // reloaded.
  environment.moduleGraph.invalidateAll()

  environment.hot.send({
    type: 'full-reload',
    path: '*',
  })
}

