export function convertEsbuildPluginToRolldownPlugin(
  esbuildPlugin: esbuild.Plugin,
): RolldownPlugin {
  const onStartCallbacks: Array<() => void> = []
  const onEndCallbacks: Array<(buildResult: esbuild.BuildResult) => void> = []
  const onDisposeCallbacks: Array<() => void> = []
  let resolveIdHandlers: ResolveIdHandler[]
  let loadHandlers: LoadHandler[]

  let isSetupDone = false
  const setup = async (
    plugins: RolldownPluginOption[],
    platform: 'browser' | 'node' | 'neutral',
  ) => {
    const onResolveCallbacks: Array<
      [options: esbuild.OnResolveOptions, callback: EsbuildOnResolveCallback]
    > = []
    const onLoadCallbacks: Array<
      [options: esbuild.OnLoadOptions, callback: EsbuildOnLoadCallback]
    > = []

    const pluginBuild: esbuild.PluginBuild = {
      initialOptions: new Proxy(
        {
          platform,
          plugins:
            plugins?.flatMap((p) =>
              p && 'name' in p
                ? [
                    {
                      name: p.name,
                      // eslint-disable-next-line @typescript-eslint/no-empty-function
                      setup() {},
                    },
                  ]
                : [],
            ) ?? [],
        },
        {
          get(target, p, _receiver) {
            if (p in target) return (target as any)[p]
            throw new Error('Not implemented')
          },
        },
      ) as esbuild.BuildOptions,
      resolve() {
        throw new Error('Not implemented')
      },
      onStart(callback) {
        onStartCallbacks.push(callback)
      },
      onEnd(callback) {
        onEndCallbacks.push(callback)
      },
      onResolve(options, callback) {
        onResolveCallbacks.push([options, callback])
      },
      onLoad(options, callback) {
        onLoadCallbacks.push([options, callback])
      },
      onDispose(callback) {
        onDisposeCallbacks.push(callback)
      },
      get esbuild(): esbuild.PluginBuild['esbuild'] {
        throw new Error('Not implemented')
      },
      set esbuild(_: unknown) {
        throw new Error('Not implemented')
      },
    }

    await esbuildPlugin.setup(pluginBuild)

    resolveIdHandlers = onResolveCallbacks.map(([options, callback]) =>
      createResolveIdHandler(options, callback),
    )
    loadHandlers = onLoadCallbacks.map(([options, callback]) =>
      createLoadHandler(options, callback),
    )
    isSetupDone = true
  }

  const usedNamespaces = new Set<string>()
  return {
    name: esbuildPlugin.name,
    async options(inputOptions) {
      await setup(
        inputOptions.plugins as RolldownPluginOption[],
        inputOptions.platform ?? 'node',
      )
    },
    async buildStart(inputOptions) {
      // options hook is not called for scanner
      if (!isSetupDone) {
        // inputOptions.plugins is not available for buildStart hook
        // put a dummy plugin to tell that this is a scan
        await setup(
          [{ name: 'vite:dep-scan' }],
          inputOptions.platform ?? 'node',
        )
      }

      for (const cb of onStartCallbacks) {
        cb()
      }
    },
    generateBundle(_outputOpts, _bundle, isWrite) {
      const buildResult = new Proxy(
        {
          metafile: undefined,
          mangleCache: undefined,
          ...(isWrite ? { outputFiles: undefined } : {}),
        } as esbuild.BuildResult,
        {
          get(_target, prop) {
            if (prop in _target || typeof prop === 'symbol') {
              return (_target as any)[prop]
            }
            throw new Error('Not implemented property: ' + prop)
          },
        },
      )
      for (const cb of onEndCallbacks) {
        cb(buildResult)
      }
    },
    async resolveId(id, importer, opts) {
      for (const handler of resolveIdHandlers) {
        const result = await handler.call(this, id, importer, opts)
        if (result) {
          if (typeof result === 'object' && result.namespace) {
            usedNamespaces.add(result.namespace)
          }
          return result
        }
      }
      if (usedNamespaces.size) {
        const [importerWithoutNamespace, namespaceFromImporter] =
          idToPathAndNamespace(importer)
        if (usedNamespaces.has(namespaceFromImporter)) {
          return await this.resolve(id, importerWithoutNamespace, opts)
        }
      }
    },
    async load(id) {
      for (const handler of loadHandlers) {
        const result = await handler.call(this, id)
        if (result) {
          return result
        }
      }
    },
    closeBundle() {
      if (!this.meta.watchMode) {
        for (const cb of onDisposeCallbacks) {
          cb()
        }
      }
    },
    closeWatcher() {
      for (const cb of onDisposeCallbacks) {
        cb()
      }
    },
  }
}

function createResolveIdHandler(
  options: esbuild.OnResolveOptions,
  callback: EsbuildOnResolveCallback,
): ResolveIdHandler {
  return async function (id, importer, opts) {
    const [importerWithoutNamespace, importerNamespace] =
      idToPathAndNamespace(importer)
    if (
      options.namespace !== undefined &&
      options.namespace !== importerNamespace
    ) {
      return
    }
    if (options.filter !== undefined && !options.filter.test(id)) {
      return
    }

    const result = await callback({
      path: id,
      importer: importerWithoutNamespace ?? '',
      namespace: importerNamespace,
      resolveDir: dirname(importerWithoutNamespace ?? ''),
      kind:
        importerWithoutNamespace === undefined
          ? 'entry-point'
          : opts.kind === 'new-url' || opts.kind === 'hot-accept'
            ? 'dynamic-import'
            : opts.kind,
      pluginData: {},
      with: {},
    })
    if (!result) return
    if (result.errors && result.errors.length > 0) {
      throw new AggregateError(result.errors)
    }
    if (
      (result.warnings && result.warnings.length > 0) ||
      (result.watchDirs && result.watchDirs.length > 0) ||
      !result.path
    ) {
      throw new Error('not implemented')
    }
    for (const file of result.watchFiles ?? []) {
      this.addWatchFile(file)
    }

    return {
      id: result.namespace ? `${result.namespace}:${result.path}` : result.path,
      external: result.external,
      moduleSideEffects: result.sideEffects,
      namespace: result.namespace,
    }
  }
}

function createLoadHandler(
  options: esbuild.OnLoadOptions,
  callback: EsbuildOnLoadCallback,
): LoadHandler {
  const textDecoder = new TextDecoder()
  return async function (id) {
    const [idWithoutNamespace, idNamespace] = idToPathAndNamespace(id)
    if (
      options.namespace !== undefined &&
      options.namespace !== 'file' &&
      options.namespace !== idNamespace
    ) {
      return
    }
    if (options.filter !== undefined && !options.filter.test(id)) {
      return
    }

    const result = await callback.call(this, {
      path: idWithoutNamespace,
      namespace: idNamespace,
      suffix: '',
      pluginData: {},
      with: {},
    })
    if (!result) return
    if (result.errors && result.errors.length > 0) {
      throw new AggregateError(result.errors)
    }
    if (
      (result.warnings && result.warnings.length > 0) ||
      (result.watchDirs && result.watchDirs.length > 0) ||
      result.contents == null
    ) {
      throw new Error('not implemented')
    }
    for (const file of result.watchFiles ?? []) {
      this.addWatchFile(file)
    }

    return {
      code:
        typeof result.contents === 'string'
          ? result.contents
          : textDecoder.decode(result.contents),
      moduleType: result.loader,
    }
  }
}

function idToPathAndNamespace(
  id: string | undefined,
): [path: string | undefined, namespace: string] {
  if (id === undefined) return [undefined, 'file']

  const namespaceIndex = id.indexOf(':')
  if (namespaceIndex >= 0) {
    return [id.slice(namespaceIndex + 1), id.slice(0, namespaceIndex)]
  } else {
    return [id, 'file']
  }
}

export function createOptimizeDepsIncludeResolver(
  environment: Environment,
): (id: string) => Promise<string | undefined> {
  const topLevelConfig = environment.getTopLevelConfig()
  const resolve = createBackCompatIdResolver(topLevelConfig, {
    asSrc: false,
    scan: true,
    packageCache: new Map(),
  })

  return async (id: string) => {
    const lastArrowIndex = id.lastIndexOf('>')
    if (lastArrowIndex === -1) {
      return await resolve(environment, id, undefined)
    }
    // split nested selected id by last '>', for example:
    // 'foo > bar > baz' => 'foo > bar' & 'baz'
    const nestedRoot = id.substring(0, lastArrowIndex).trim()
    const nestedPath = id.substring(lastArrowIndex + 1).trim()
    const basedir = nestedResolveBasedir(
      nestedRoot,
      topLevelConfig.root,
      topLevelConfig.resolve.preserveSymlinks,
    )
    return await resolve(
      environment,
      nestedPath,
      path.resolve(basedir, 'package.json'),
    )
  }
}

export function expandGlobIds(id: string, config: ResolvedConfig): string[] {
  const pkgName = getNpmPackageName(id)
  if (!pkgName) return []

  const pkgData = resolvePackageData(
    pkgName,
    config.root,
    config.resolve.preserveSymlinks,
    config.packageCache,
  )
  if (!pkgData) return []

  const pattern = '.' + id.slice(pkgName.length)
  const exports = pkgData.data.exports

  // if package has exports field, get all possible export paths and apply
  // glob on them with picomatch
  if (exports) {
    if (typeof exports === 'string' || Array.isArray(exports)) {
      return [pkgName]
    }

    const possibleExportPaths: string[] = []
    for (const key in exports) {
      if (key[0] === '.') {
        if (key.includes('*')) {
          // "./glob/*": {
          //   "browser": "./dist/glob/*-browser/*.js", <-- get this one
          //   "default": "./dist/glob/*/*.js"
          // }
          // NOTE: theoretically the "default" condition could map to a different
          // set of files, but that complicates the resolve logic, so we assume
          // all conditions map to the same set of files, and get the first one.
          const exportsValue = getFirstExportStringValue(exports[key])
          if (!exportsValue) continue

          // "./dist/glob/*-browser/*.js" => "./dist/glob/**/*-browser/**/*.js"
          // NOTE: in some cases, this could expand to consecutive /**/*/**/* etc
          // but it's fine since `tinyglobby` handles it the same.
          const exportValuePattern = exportsValue.replace(/\*/g, '**/*')
          // "./dist/glob/*-browser/*.js" => /dist\/glob\/(.*)-browser\/(.*)\.js/
          const exportsValueGlobRe = new RegExp(
            exportsValue.split('*').map(escapeRegex).join('(.*)'),
          )

          possibleExportPaths.push(
            ...globSync(exportValuePattern, {
              cwd: pkgData.dir,
              expandDirectories: false,
              ignore: ['node_modules'],
            })
              .map((filePath) => {
                // `tinyglobby` returns paths as they are formatted by the underlying `fdir`.
                // Both `globSync("./some-dir/**/*")` and `globSync("./**/*")` result in
                // `"some-dir/somefile"` being returned, so we ensure the correct prefix manually.
                if (exportsValue.startsWith('./')) {
                  filePath = './' + filePath
                }

                // "./glob/*": "./dist/glob/*-browser/*.js"
                // `filePath`: "./dist/glob/foo-browser/foo.js"
                // we need to revert the file path back to the export key by
                // matching value regex and replacing the capture groups to the key
                const matched = exportsValueGlobRe.exec(slash(filePath))
                // `matched`: [..., 'foo', 'foo']
                if (matched) {
                  let allGlobSame = matched.length === 2
                  // exports key can only have one *, so for >=2 matched groups,
                  // make sure they have the same value
                  if (!allGlobSame) {
                    // assume true, if one group is different, set false and break
                    allGlobSame = true
                    for (let i = 2; i < matched.length; i++) {
                      if (matched[i] !== matched[i - 1]) {
                        allGlobSame = false
                        break
                      }
                    }
                  }
                  if (allGlobSame) {
                    return key.replace('*', matched[1]).slice(2)
                  }
                }
                return ''
              })
              .filter(Boolean),
          )
        } else {
          // null export value means the subpath is intentionally private/blocked
          // https://nodejs.org/api/packages.html#subpath-patterns
          if (exports[key] == null) continue
          possibleExportPaths.push(key.slice(2))
        }
      }
    }

    const isMatch = picomatch(pattern)
    const matched = possibleExportPaths
      .filter((p) => isMatch(p))
      .map((match) => path.posix.join(pkgName, match))
    matched.unshift(pkgName)
    return matched
  } else {
    // for packages without exports, we can do a simple glob
    const matched = globSync(pattern, {
      cwd: pkgData.dir,
      expandDirectories: false,
      ignore: ['node_modules'],
    }).map((match) => path.posix.join(pkgName, slash(match)))
    matched.unshift(pkgName)
    return matched
  }
}

function getFirstExportStringValue(
  obj: string | string[] | Record<string, any>,
): string | undefined {
  if (typeof obj === 'string') {
    return obj
  } else if (Array.isArray(obj)) {
    return obj[0]
  } else {
    for (const key in obj) {
      return getFirstExportStringValue(obj[key])
    }
  }
}

function nestedResolveBasedir(
  id: string,
  basedir: string,
  preserveSymlinks = false,
) {
  const pkgs = id.split('>').map((pkg) => pkg.trim())
  for (const pkg of pkgs) {
    basedir = resolvePackageData(pkg, basedir, preserveSymlinks)?.dir || basedir
  }
  return basedir
}

const resolveAssets = (resolved: string, kind: ImportKind) => {
  if (kind === 'require-call') {
    // here it is not set to `external: true` to convert `require` to `import`
    return {
      id: externalWithConversionNamespace + resolved,
    }
  }
  return {
    id: resolved,
    external: 'absolute' as const,
  }
}

const resolve = (
  id: string,
  importer: string | undefined,
  kind: ImportKind,
): Promise<string | undefined> => {
  // map importer ids to file paths for correct resolution
  const _importer =
    importer && importer in qualified ? qualified[importer] : importer
  const resolver = kind.startsWith('require') ? _resolveRequire : _resolve
  return resolver(environment, id, _importer)
}

const resolveResult = (id: string, resolved: string, kind: ImportKind) => {
  if (resolved.startsWith(browserExternalId)) {
    return {
      id: browserExternalNamespace + id,
    }
  }
  if (resolved.startsWith(optionalPeerDepId)) {
    return {
      id: optionalPeerDepNamespace + resolved,
    }
  }
  if (allExternalTypesReg.test(resolved)) {
    return resolveAssets(resolved, kind)
  }
  if (isBuiltin(environment.config.resolve.builtins, resolved)) {
    return
  }
  if (isExternalUrl(resolved)) {
    return {
      id: resolved,
      external: 'absolute',
    }
  }
  return {
    id: path.resolve(resolved),
  }
}

function resolveEntry(id: string) {
  const flatId = flattenId(id)
  if (flatId in qualified) {
    return {
      id: qualified[flatId],
    }
  }
}

async handler(id, importer, options) {
  const kind = options.kind
  // if the prefix exist, it is already converted to `import`, so set `external: true`
  if (id.startsWith(convertedExternalPrefix)) {
    return {
      id: id.slice(convertedExternalPrefix.length),
      external: 'absolute',
    }
  }

  const resolved = await resolve(id, importer, kind)
  if (resolved) {
    // `resolved` can be javascript even when `id` matches `allExternalTypes`
    // due to cjs resolution (e.g. require("./test.pdf") for "./test.pdf.js")
    // or package name (e.g. import "some-package.pdf")
    if (JS_TYPES_RE.test(resolved)) {
      return {
        // normalize to \\ on windows for esbuild/rolldown behavior difference: https://github.com/sapphi-red-repros/rolldown-esbuild-path-normalization
        id: isWindows ? resolved.replaceAll('/', '\\') : resolved,
        external: false,
      }
    }
    return resolveAssets(resolved, kind)
  }
},

handler(id) {
  const path = id.slice(externalWithConversionNamespace.length)
  // import itself with prefix (this is the actual part of require-import conversion)
  const modulePath = `"${convertedExternalPrefix}${path}"`
  return {
    code:
      isCSSRequest(path) && !isModuleCSSRequest(path)
        ? `import ${modulePath};`
        : `export { default } from ${modulePath};` +
          `export * from ${modulePath};`,
  }
},

buildEnd() {
  esmPackageCache.clear()
  cjsPackageCache.clear()
},

async handler(id, importer, options) {
  const kind = options.kind

  if (moduleListContains(external, id)) {
    return {
      id: id,
      external: 'absolute',
    }
  }

  // ensure rolldown uses our resolved entries
  let entry: { id: string } | undefined
  // if this is an entry, return entry namespace resolve result
  if (!importer) {
    if ((entry = resolveEntry(id))) return entry
    // check if this is aliased to an entry - also return entry namespace
    const aliased = await _resolve(environment, id, undefined, true)
    if (aliased && (entry = resolveEntry(aliased))) {
      return entry
    }
  }

  // use vite's own resolver
  const resolved = await resolve(id, importer, kind)
  if (resolved) {
    return resolveResult(id, resolved, kind)
  }
},

    handler(id) {
      if (id.startsWith(browserExternalNamespace)) {
        const path = id.slice(browserExternalNamespace.length)
        if (isProduction) {
          return {
            code: 'module.exports = {}',
          }
        } else {
          return {
            // Return in CJS to intercept named imports. Use `Object.create` to
            // create the Proxy in the prototype to workaround esbuild issue. Why?
            //
            // In short, esbuild cjs->esm flow:
            // 1. Create empty object using `Object.create(Object.getPrototypeOf(module.exports))`.
            // 2. Assign props of `module.exports` to the object.
            // 3. Return object for ESM use.
            //
            // If we do `module.exports = new Proxy({}, {})`, step 1 returns empty object,
            // step 2 does nothing as there's no props for `module.exports`. The final object
            // is just an empty object.
            //
            // Creating the Proxy in the prototype satisfies step 1 immediately, which means
            // the returned object is a Proxy that we can intercept.
            //
            // Note: Skip keys that are accessed by esbuild and browser devtools.
            code: `\
module.exports = Object.create(new Proxy({}, {
    get(_, key) {
    if (
        key !== '__esModule' &&
        key !== '__proto__' &&
        key !== 'constructor' &&
        key !== 'splice'
    ) {
        console.warn(\`Module "${path}" has been externalized for browser compatibility. Cannot access "${path}.\${key}" in client code. See https://vite.dev/guide/troubleshooting.html#module-externalized-for-browser-compatibility for more details.\`)
    }
    }
}))`,
          }
        }
      }

      if (id.startsWith(optionalPeerDepNamespace)) {
        const path = id.slice(optionalPeerDepNamespace.length)
        const [, peerDep, parentDep] = path.split(':')
        return {
          code:
            'module.exports = {};' +
            `throw new Error(\`Could not resolve "${peerDep}" imported by "${parentDep}". Is it installed?\`)`,
        }
      }
    },

handler(code, id) {
  let s: MagicString | undefined
  const re = new RegExp(assetImportMetaUrlRE)
  const cleanString = stripLiteral(code)

  let match: RegExpExecArray | null
  while ((match = re.exec(cleanString))) {
    const [[startIndex, endIndex], [urlStart, urlEnd]] =
      match.indices as Array<[number, number]>
    if (hasViteIgnoreRE.test(code.slice(startIndex, urlStart))) continue

    const rawUrl = code.slice(urlStart, urlEnd)

    if (rawUrl[0] === '`' && rawUrl.includes('${')) {
      // We skip dynamic template strings in the optimizer for now as they
      // require complex glob transformation that is handled by the main asset plugin.
      continue
    }

    const url = rawUrl.slice(1, -1)
    if (isDataUrl(url) || isExternalUrl(url) || url.startsWith('/')) {
      continue
    }

    if (!s) s = new MagicString(code)

    // we resolve the relative path from the original library file (id) and
    // then rewrite it relative to the bundle (deps) directory.
    const absolutePath = path.resolve(path.dirname(id), url)
    const relativePath = path.relative(bundleOutputDir, absolutePath)
    const normalizedRelativePath = normalizePath(relativePath)
    s.update(
      startIndex,
      endIndex,
      // NOTE: add `'' +` to opt-out rolldown's transform: https://github.com/rolldown/rolldown/issues/2745
      `new URL('' + ${JSON.stringify(
        normalizedRelativePath,
      )}, import.meta.url)`,
    )
  }

  if (s) {
    return {
      code: s.toString(),
      map: s.generateMap({ hires: 'boundary' }),
    }
  }
},

export function rolldownCjsExternalPlugin(
  externals: string[],
  platform: 'node' | 'browser' | 'neutral',
): Plugin | undefined {
  // Skip this plugin for `platform: 'node'` as `require` is available in Node
  // and that is more accurate than converting to `import`
  if (platform === 'node') {
    return undefined
  }
  // Skip this plugin for `platform: 'neutral'` as we are not sure whether `require` is available
  if (platform === 'neutral') {
    return undefined
  }

  // Apply this plugin for `platform: 'browser'` as `require` is not available in browser and
  // converting to `import` would be necessary to make the code work
  platform satisfies 'browser'

  const filter = new RegExp(externals.map(matchesEntireLine).join('|'))

  return {
    name: 'cjs-external',
    resolveId: {
      filter: { id: [prefixRegex(nonFacadePrefix), filter] },
      handler(id, _importer, options) {
        if (id.startsWith(nonFacadePrefix)) {
          return {
            id: id.slice(nonFacadePrefix.length),
            external: 'absolute',
          }
        }
        if (options.kind === 'require-call') {
          return {
            id: cjsExternalFacadeNamespace + id,
          }
        }
        return {
          id,
          external: 'absolute',
        }
      },
    },
    load: {
      filter: { id: prefixRegex(cjsExternalFacadeNamespace) },
      handler(id) {
        const idWithoutNamespace = id.slice(cjsExternalFacadeNamespace.length)
        return {
          code: `\
import * as m from ${JSON.stringify(nonFacadePrefix + idWithoutNamespace)};
module.exports = ${isNodeBuiltin(idWithoutNamespace) ? 'm.default' : '{ ...m }'};
`,
        }
      },
    },
  }
}

get pluginContainer(): EnvironmentPluginContainer {
  if (!this._pluginContainer)
    throw new Error(
      `${this.name} environment.pluginContainer called before initialized`,
    )
  return this._pluginContainer
}

