const resolve = async (
  id: string,
  importer?: string,
  options?: Parameters<typeof resolveId>[2],
) => {
  const key = JSON.stringify([
    id,
    importer && path.dirname(importer),
    options,
  ])
  if (seen.has(key)) {
    return seen.get(key)
  }
  const resolved = await resolveId(id, importer, options)
  const res = resolved?.id
  seen.set(key, res)
  return res
}

