    return path.join(path.dirname(assetFileNames), cssAssetNameDir)
  } else {
    return path.dirname(
      assetFileNames({
        type: 'asset',
        name: cssAssetName,
        names: [cssAssetName],
        originalFileName,
        originalFileNames: originalFileName ? [originalFileName] : [],
        source: '/* vite internal call, ignore */',
      }),
    )
  }
}

