  if (mod._ssrModule) {
    // TODO: Maybe this isn't needed?
    this._ssr.invalidateModule(
      mod._ssrModule,
      new Set(
        [...seen].map((mod) => mod._ssrModule).filter(Boolean),
      ) as Set<EnvironmentModuleNode>,
      timestamp,
      isHmr,
      softInvalidate,
