private _normalizeRawLog(
  rawLog: string | RollupLog | (() => string | RollupLog),
): RollupLog {
  const logValue = typeof rawLog === 'function' ? rawLog() : rawLog
  return typeof logValue === 'string' ? new Error(logValue) : logValue
}

