functions.code:
function getSocketClient(socket: WebSocketRaw) {
  if (!clientsMap.has(socket)) {
    clientsMap.set(socket, {
      send: (...args: any[]) => {
        let payload: HotPayload
        if (typeof args[0] === 'string') {
          payload = {
            type: 'custom',
            event: args[0],
            data: args[1],
          }
        } else {
          payload = args[0]
        }
        socket.send(JSON.stringify(payload))
      },
      socket,
    })
  }
  return clientsMap.get(socket)!
}

